CREATE TABLE api_cloud_project_builds(build_id text PRIMARY KEY,account_id text NOT NULL,provider text NOT NULL,provider_sandbox_id text,settings jsonb NOT NULL,created_at bigint NOT NULL);
CREATE TABLE api_cloud_runtime_observations(provider text,provider_sandbox_id text,observation jsonb NOT NULL,PRIMARY KEY(provider,provider_sandbox_id));
CREATE TABLE api_provider_usage_events(provider text,event_id text,type text NOT NULL,provider_resource_id text,payload jsonb NOT NULL,received_at bigint NOT NULL,expires_at bigint NOT NULL,PRIMARY KEY(provider,event_id));
CREATE TABLE api_provider_event_finalizations(provider text,event_id text,provider_execution_id text,finalized_at bigint NOT NULL,expires_at bigint NOT NULL,PRIMARY KEY(provider,event_id),UNIQUE(provider,provider_execution_id));
CREATE TABLE api_cloud_billing_periods(period_id text PRIMARY KEY,account_id text NOT NULL,billing_provider text NOT NULL DEFAULT 'stripe',provider_subscription_id text,status text NOT NULL,currency text NOT NULL DEFAULT 'USD',period_start bigint NOT NULL,period_end bigint NOT NULL,base_price_micros bigint NOT NULL,included_provider_cost_micros bigint NOT NULL,markup_basis_points bigint NOT NULL,overage_cap_micros bigint NOT NULL,price_catalog_version text NOT NULL DEFAULT 'original',created_at bigint NOT NULL,updated_at bigint NOT NULL,UNIQUE(account_id,period_start));
CREATE TABLE api_cloud_billing_usage(entry_id text PRIMARY KEY,period_id text NOT NULL,account_id text NOT NULL,resource_kind text NOT NULL,resource_id text NOT NULL,provider text NOT NULL,provider_event_id text,provider_execution_id text,started_at bigint NOT NULL,ended_at bigint NOT NULL,vcpu_count bigint NOT NULL,memory_mib bigint NOT NULL,provider_cost_micros bigint NOT NULL,status text NOT NULL,created_at bigint NOT NULL,UNIQUE(provider,provider_event_id),UNIQUE(provider,provider_execution_id,period_id));
CREATE TABLE api_cloud_billing_ledger(entry_id text PRIMARY KEY,period_id text NOT NULL,account_id text NOT NULL,kind text NOT NULL,amount_micros bigint NOT NULL,source_id text NOT NULL,metadata jsonb NOT NULL DEFAULT '{}',occurred_at bigint NOT NULL,created_at bigint NOT NULL,UNIQUE(kind,source_id));
CREATE TABLE api_cloud_billing_reservations(period_id text NOT NULL,account_id text NOT NULL,resource_kind text NOT NULL,resource_id text NOT NULL,provider text NOT NULL,provider_cost_micros bigint NOT NULL,started_at bigint NOT NULL,vcpu_count bigint NOT NULL,memory_mib bigint NOT NULL,expires_at bigint NOT NULL,updated_at bigint NOT NULL,PRIMARY KEY(period_id,resource_kind,resource_id));
CREATE TABLE api_cloud_billing_outbox(outbox_id text PRIMARY KEY,period_id text NOT NULL,account_id text NOT NULL,provider text NOT NULL,amount_cents bigint NOT NULL,idempotency_key text NOT NULL,attempt_count bigint NOT NULL DEFAULT 0,next_attempt_at bigint NOT NULL,acknowledged_at bigint,last_error text,created_at bigint NOT NULL,occurred_at bigint NOT NULL,UNIQUE(provider,idempotency_key));
CREATE TABLE api_cloud_usage_outbox(event_id text PRIMARY KEY,payload jsonb NOT NULL,created_at bigint NOT NULL,next_attempt_at bigint NOT NULL,attempt_count bigint NOT NULL DEFAULT 0,acknowledged_at bigint,last_error text);
